compile.workshop:
variables {
    global:
        0: g
}

rule ("default comparison") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.g, ==, 1));
            Set Global Variable(g, 2);
    }
}

rule ("aggressive alone comparison") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.g, ==, 1));
            Set Global Variable(g, 2);
    }
}

//Optimize for size enabled
rule ("tail comparison") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.g, ==, 1));
            Set Global Variable(g, 2);
    }
}

rule ("tail negation") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip If(Global.g, True);
        Set Global Variable(g, 2);
        //__label_if_2__:
    }
}

rule ("tail negated equality") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.g, !=, 1));
            Set Global Variable(g, 2);
    }
}

rule ("tail negated inequality") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.g, ==, 1));
            Set Global Variable(g, 2);
    }
}

rule ("tail negated less than") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.g, >=, 1));
            Set Global Variable(g, 2);
    }
}

rule ("tail negated less than or equal") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.g, >, 1));
            Set Global Variable(g, 2);
    }
}

rule ("tail negated greater than") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.g, <=, 1));
            Set Global Variable(g, 2);
    }
}

rule ("tail negated greater than or equal") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.g, <, 1));
            Set Global Variable(g, 2);
    }
}

rule ("tail double negated equality") {
